    if (maxQps <= 0) throw new IllegalArgumentException("maxQps must be positive");
    if (minRtMs <= 0) throw new IllegalArgumentException("min rt must be positive");
    if (rtHardLimitMs < minRtMs) throw new IllegalArgumentException("rt hard limit below min rt");
    if (threadLimit < 0) throw new IllegalArgumentException("thread limit must be non-negative");
    if (loadTenth == null || rtMs == null || inflight == null || inQps == null || isEntry == null) {
      throw new IllegalArgumentException("array length mismatch");
    }
    int n = loadTenth.length;
    if (rtMs.length != n || inflight.length != n || inQps.length != n || isEntry.length != n) {
      throw new IllegalArgumentException("array length mismatch");
    }
    final int loadLimit = cores * 25;
    long admittedTotal = 0, deniedTotal = 0;
    int gateTicks = 0, lastFullBlock = -1;
    for (int i = 0; i < n; i++) {
      if (loadTenth[i] < 0) throw new IllegalArgumentException("negative load");
      if (rtMs[i] < 0) throw new IllegalArgumentException("negative rt");
      if (inflight[i] < 0) throw new IllegalArgumentException("negative inflight");
      if (inQps[i] < 0) throw new IllegalArgumentException("negative qps");
      if (isEntry[i] != 0 && isEntry[i] != 1) throw new IllegalArgumentException("isEntry must be 0 or 1");
      int ok;
      if (loadTenth[i] > loadLimit || rtMs[i] > rtHardLimitMs || inflight[i] > threadLimit) {
        if (loadTenth[i] > loadLimit) gateTicks++;
        ok = 0;
      } else {
        ok = inQps[i];
      }
      admittedTotal += ok;
      deniedTotal += inQps[i] - ok;
      if (ok == 0 && inQps[i] > 0) lastFullBlock = i;
    }
    return new int[] {(int) admittedTotal, (int) deniedTotal, gateTicks, lastFullBlock};
  }
}
